public sealed class Viewport3DControl:Grid {readonly Viewport3D view=new();readonly Model3DGroup scene=new();readonly PerspectiveCamera camera=new(){FieldOfView=55,UpDirection=new Vector3D(0,0,1)};readonly Dictionary<Model3D,Guid> objectModels=new();readonly Dictionary<Model3D,GizmoAxis> gizmoModels=new();readonly WallMeshBuilder wallMeshes=new();readonly StairMeshBuilder stairMeshes=new();readonly ViewportMaterialResolver materials=new();readonly StudioBuildTools buildTools=new();ShellProject? project;Guid? selected;Point? orbitStart;Point? dragStart;Vec3? dragPositionStart,dragRotationStart,dragScaleStart;GizmoAxis activeAxis=GizmoAxis.None;TransformMode mode=TransformMode.Move;bool openingPlacement,openingDoor;float openingWidth=1,openingHeight=2.1f,openingSill;double yaw=.7,pitch=.55,distance=18;Point3D cameraTarget=new(0,0,1.5);public event Action<Guid>? ObjectSelected;public event Action? ObjectTransformed;public event Action<Guid,float,float,float,float,bool>? WallOpeningRequested;public Viewport3DControl(){Focusable=true;Background=new SolidColorBrush(Color.FromRgb(12,12,16));view.Camera=camera;view.Children.Add(new ModelVisual3D{Content=scene});Children.Add(view);MouseWheel+=Wheel;MouseRightButtonDown+=OrbitDown;MouseRightButtonUp+=OrbitUp;MouseLeftButtonDown+=LeftDown;MouseLeftButtonUp+=LeftUp;MouseMove+=Move;KeyDown+=Keys;Loaded+=(_,_)=>{UpdateCamera();RenderScene();};}public void SetProject(ShellProject p,Guid? selectedId=null){project=p;selected=selectedId;RenderScene();}public void SetMode(TransformMode value){mode=value;openingPlacement=false;RenderScene();}public void FocusSelection(){if(project==null||selected==null)return;var obj=project.Objects.FirstOrDefault(x=>x.Id==selected);if(obj==null)return;cameraTarget=new Point3D(obj.Position.X,obj.Position.Y,obj.Position.Z);distance=Math.Clamp(Math.Max(obj.Scale.X,Math.Max(obj.Scale.Y,obj.Scale.Z))*3,4,30);UpdateCamera();}public void BeginWallOpeningPlacement(bool door,float width,float height,float sill){openingPlacement=true;openingDoor=door;openingWidth=Math.Max(.1f,width);openingHeight=Math.Max(.1f,height);openingSill=door?0:Math.Max(0,sill);Cursor=Cursors.Cross;RenderScene();}public void CancelWallOpeningPlacement(){openingPlacement=false;Cursor=Cursors.Arrow;RenderScene();}public void RenderScene(){scene.Children.Clear();objectModels.Clear();gizmoModels.Clear();scene.Children.Add(new AmbientLight(Color.FromRgb(110,110,125)));scene.Children.Add(new DirectionalLight(Colors.White,new Vector3D(-.4,.6,-1)));DrawGrid();if(project==null)return;foreach(var obj in project.Objects){var model=Model(obj,obj.Id==selected);objectModels[model]=obj.Id;scene.Children.Add(model);}if(!openingPlacement&&selected is Guid id){var obj=project.Objects.FirstOrDefault(x=>x.Id==id);if(obj!=null)DrawGizmo(obj);}}GeometryModel3D Model(SceneObject obj,bool active){MeshGeometry3D mesh;if(obj.Type==SceneObjectType.Wall&&project!=null)mesh=wallMeshes.Build(obj,project.WallOpenings.Where(x=>x.WallId==obj.Id));else if(obj.Type==SceneObjectType.Stairs)mesh=stairMeshes.Build(obj);else mesh=BoxMesh(obj.Scale);var fallback=active?Color.FromRgb(176,132,245):obj.Type==SceneObjectType.Prop?Color.FromRgb(125,90,190):Color.FromRgb(105,76,165);var mat=project==null?new DiffuseMaterial(new SolidColorBrush(fallback)):materials.Resolve(project,obj,fallback);var model=new GeometryModel3D(mesh,mat){BackMaterial=mat};var transform=new Transform3DGroup();transform.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),obj.Rotation.X)));transform.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,1,0),obj.Rotation.Y)));transform.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),obj.Rotation.Z)));var z=obj.Type is SceneObjectType.Wall or SceneObjectType.Stairs?obj.Position.Z-obj.Scale.Z/2:obj.Position.Z;transform.Children.Add(new TranslateTransform3D(obj.Position.X,obj.Position.Y,z));model.Transform=transform;return model;}static MeshGeometry3D BoxMesh(Vec3 scale){var sx=Math.Max(.02,scale.X)/2;var sy=Math.Max(.02,scale.Y)/2;var sz=Math.Max(.02,scale.Z)/2;return new MeshGeometry3D{Positions=new Point3DCollection{new(-sx,-sy,-sz),new(sx,-sy,-sz),new(sx,sy,-sz),new(-sx,sy,-sz),new(-sx,-sy,sz),new(sx,-sy,sz),new(sx,sy,sz),new(-sx,sy,sz)},TriangleIndices=new Int32Collection{0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7}};}void DrawGizmo(SceneObject obj){var origin=new Point3D(obj.Position.X,obj.Position.Y,obj.Position.Z);var width=mode==TransformMode.Rotate?.1:.065;scene.Children.Add(Axis(origin,new Vector3D(2.4,0,0),Colors.Red,GizmoAxis.X,width));scene.Children.Add(Axis(origin,new Vector3D(0,2.4,0),Colors.LimeGreen,GizmoAxis.Y,width));scene.Children.Add(Axis(origin,new Vector3D(0,0,2.4),Colors.DodgerBlue,GizmoAxis.Z,width));}GeometryModel3D Axis(Point3D point,Vector3D direction,Color color,GizmoAxis axis,double width){var model=Line(point,point+direction,width,color);gizmoModels[model]=axis;return model;}void DrawGrid(){for(int i=-30;i<=30;i++){var major=i%5==0;var color=major?Color.FromRgb(58,58,72):Color.FromRgb(38,38,48);scene.Children.Add(Line(new Point3D(i,-30,0),new Point3D(i,30,0),major?.016:.009,color));scene.Children.Add(Line(new Point3D(-30,i,0),new Point3D(30,i,0),major?.016:.009,color));}}GeometryModel3D Line(Point3D a,Point3D b,double width,Color color){var direction=b-a;var len=direction.Length;var mesh=new MeshGeometry3D{Positions=new Point3DCollection{new(-width,-len/2,0),new(width,-len/2,0),new(width,len/2,0),new(-width,len/2,0)},TriangleIndices=new Int32Collection{0,1,2,0,2,3}};var mat=new DiffuseMaterial(new SolidColorBrush(color));var model=new GeometryModel3D(mesh,mat){BackMaterial=mat};var angle=Math.Atan2(direction.Y,direction.X)*180/Math.PI-90;var transform=new Transform3DGroup();transform.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),angle)));if(Math.Abs(direction.Z)>Math.Abs(direction.X)+Math.Abs(direction.Y))transform.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),90)));transform.Children.Add(new TranslateTransform3D((a.X+b.X)/2,(a.Y+b.Y)/2,(a.Z+b.Z)/2));model.Transform=transform;return model;}void OrbitDown(object s,MouseButtonEventArgs e){Focus();orbitStart=e.GetPosition(this);CaptureMouse();}void OrbitUp(object s,MouseButtonEventArgs e){orbitStart=null;if(activeAxis==GizmoAxis.None&&IsMouseCaptured)ReleaseMouseCapture();}void LeftDown(object s,MouseButtonEventArgs e){Focus();var hit=VisualTreeHelper.HitTest(view,e.GetPosition(view)) as RayMeshGeometry3DHitTestResult;if(hit?.ModelHit is not Model3D model)return;if(openingPlacement&&objectModels.TryGetValue(model,out var wallId)&&project!=null){var wall=project.Objects.FirstOrDefault(x=>x.Id==wallId);if(wall?.Type==SceneObjectType.Wall){var local=hit.PointHit;var inverse=model.Transform?.Inverse;if(inverse!=null)local=inverse.Transform(hit.PointHit);var offset=(float)local.X+wall.Scale.X/2;offset=Math.Clamp(offset,openingWidth/2,Math.Max(openingWidth/2,wall.Scale.X-openingWidth/2));WallOpeningRequested?.Invoke(wall.Id,offset,openingWidth,openingHeight,openingSill,openingDoor);selected=wall.Id;CancelWallOpeningPlacement();ObjectSelected?.Invoke(wall.Id);e.Handled=true;return;}}if(gizmoModels.TryGetValue(model,out var axis)&&axis!=GizmoAxis.None&&selected!=null){activeAxis=axis;dragStart=e.GetPosition(this);var obj=project?.Objects.FirstOrDefault(x=>x.Id==selected);if(obj!=null){dragPositionStart=obj.Position;dragRotationStart=obj.Rotation;dragScaleStart=obj.Scale;}CaptureMouse();e.Handled=true;return;}if(objectModels.TryGetValue(model,out var id)){selected=id;ObjectSelected?.Invoke(id);RenderScene();e.Handled=true;}}void LeftUp(object s,MouseButtonEventArgs e){activeAxis=GizmoAxis.None;dragStart=null;dragPositionStart=dragRotationStart=dragScaleStart=null;if(orbitStart==null&&IsMouseCaptured)ReleaseMouseCapture();}void Move(object s,MouseEventArgs e){if(orbitStart!=null&&e.RightButton==MouseButtonState.Pressed){var point=e.GetPosition(this);yaw+=(point.X-orbitStart.Value.X)*.01;pitch=Math.Clamp(pitch+(point.Y-orbitStart.Value.Y)*.01,-1.35,1.35);orbitStart=point;UpdateCamera();return;}if(activeAxis==GizmoAxis.None||dragStart==null||selected==null||project==null||e.LeftButton!=MouseButtonState.Pressed)return;var obj=project.Objects.FirstOrDefault(x=>x.Id==selected);if(obj==null)return;var now=e.GetPosition(this);var raw=(float)((now.X-dragStart.Value.X-(now.Y-dragStart.Value.Y))*.015);if(mode==TransformMode.Move&&dragPositionStart is Vec3 startPosition){var next=activeAxis switch{GizmoAxis.X=>new Vec3(startPosition.X+raw,startPosition.Y,startPosition.Z),GizmoAxis.Y=>new Vec3(startPosition.X,startPosition.Y+raw,startPosition.Z),GizmoAxis.Z=>new Vec3(startPosition.X,startPosition.Y,startPosition.Z+raw),_=>startPosition};var grid=project.Settings.GridSize;if(project.Settings.SnapEnabled&&grid>0)next=new Vec3(Snap(next.X,grid),Snap(next.Y,grid),Snap(next.Z,grid));if(project.Settings.SnapEnabled)next=buildTools.SmartSnap(project,obj,next,Math.Max(.1f,grid));obj.Position=next;}else if(mode==TransformMode.Rotate&&dragRotationStart is Vec3 rotation){var degrees=MathF.Round(raw*15f)*5f;obj.Rotation=activeAxis switch{GizmoAxis.X=>new Vec3(rotation.X+degrees,rotation.Y,rotation.Z),GizmoAxis.Y=>new Vec3(rotation.X,rotation.Y+degrees,rotation.Z),GizmoAxis.Z=>new Vec3(rotation.X,rotation.Y,rotation.Z+degrees),_=>rotation};}else if(mode==TransformMode.Scale&&dragScaleStart is Vec3 scale){var amount=raw*.35f;obj.Scale=activeAxis switch{GizmoAxis.X=>new Vec3(Math.Max(.05f,scale.X+amount),scale.Y,scale.Z),GizmoAxis.Y=>new Vec3(scale.X,Math.Max(.05f,scale.Y+amount),scale.Z),GizmoAxis.Z=>new Vec3(scale.X,scale.Y,Math.Max(.05f,scale.Z+amount)),_=>scale};}RenderScene();ObjectTransformed?.Invoke();}void Keys(object s,KeyEventArgs e){var pan=Math.Max(.2,distance*.025);if(e.Key==Key.F){FocusSelection();e.Handled=true;return;}if(e.Key==Key.Home){cameraTarget=new Point3D(0,0,1.5);distance=18;UpdateCamera();e.Handled=true;return;}if(e.Key==Key.Left)cameraTarget.X-=pan;if(e.Key==Key.Right)cameraTarget.X+=pan;if(e.Key==Key.Up)cameraTarget.Y+=pan;if(e.Key==Key.Down)cameraTarget.Y-=pan;UpdateCamera();}void Wheel(object s,MouseWheelEventArgs e){distance=Math.Clamp(distance-e.Delta/120.0,2,100);UpdateCamera();}void UpdateCamera(){var cp=Math.Cos(pitch);var offset=new Vector3D(Math.Cos(yaw)*cp*distance,Math.Sin(yaw)*cp*distance,Math.Sin(pitch)*distance);camera.Position=cameraTarget+offset;camera.LookDirection=cameraTarget-camera.Position;}static float Snap(float value,float grid)=>MathF.Round(value/grid)*grid;enum GizmoAxis{None,X,Y,Z}}
